import React, { useEffect } from "react";
import { useFormik } from "formik";
import { useHistory, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import * as Yup from "yup";
import { loginUserAction } from "../../redux/slices/users/usersSlices";
import DisabledButton from "../../components/DisableButton";

// Form validations
const formSchema = Yup.object({
  email: Yup.string().required("Email is required"),
  password: Yup.string().required("Password is required"),
});

const Login = () => {
  const history = useHistory();
  const dispatch = useDispatch();

  const user = useSelector((state) => state?.users);
  const { userAppErr, userServerErr, userLoading, userAuth } = user;

  const formik = useFormik({
    initialValues: {
      email: "",
      password: "",
    },
    onSubmit: (values) => {
      dispatch(loginUserAction(values));
    },
    validationSchema: formSchema,
  });

  // Redirect
  useEffect(() => {
    if (userAuth) {
      userAuth?.isAdmin ? history.push("/dashboard") : history.push("/profile");
    }
  }, [userAuth, history]);

  return (
    <section className="min-h-screen bg-[#6b6bcc] flex items-center justify-center p-4">
      <div className="max-w-5xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row p-8 md:p-12">
        
        {/* Left Side - Text / Graphic */}
        <div className="w-full md:w-1/2 flex items-center justify-center p-6 text-center md:text-left mb-8 md:mb-0">
          <h2 className="text-3xl md:text-4xl font-extrabold text-gray-800 leading-tight">
            Keep Track of your <span className="text-[#6b6bcc]">income</span> and <span className="text-green-500">expenses</span> flow
          </h2>
        </div>

        {/* Right Side - Form */}
        <div className="w-full md:w-1/2 flex flex-col justify-center px-4 md:px-10">
          <form onSubmit={formik.handleSubmit} className="w-full max-w-sm mx-auto">
            <h3 className="text-3xl font-bold text-gray-800 text-center mb-8">User Login</h3>

            {/* Error Message */}
            {(userAppErr || userServerErr) && (
              <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 mb-6 rounded-md" role="alert">
                <p>{userServerErr} {userAppErr}</p>
              </div>
            )}

            {/* Email Input */}
            <div className="mb-5 relative">
              <div className="relative flex items-center">
                <i className="fa fa-envelope absolute left-5 text-gray-400" aria-hidden="true"></i>
                <input
                  value={formik.values.email}
                  onChange={formik.handleChange("email")}
                  onBlur={formik.handleBlur("email")}
                  className="w-full bg-gray-100 text-gray-700 rounded-full py-4 pl-12 pr-6 focus:outline-none focus:ring-2 focus:ring-[#57b846] transition-all"
                  type="email"
                  name="email"
                  placeholder="Email"
                />
              </div>
              <div className="text-red-500 text-sm mt-1 ml-4">
                {formik.touched.email && formik.errors.email}
              </div>
            </div>

            {/* Password Input */}
            <div className="mb-6 relative">
              <div className="relative flex items-center">
                <i className="fa fa-lock absolute left-5 text-gray-400" aria-hidden="true"></i>
                <input
                  value={formik.values.password}
                  onChange={formik.handleChange("password")}
                  onBlur={formik.handleBlur("password")}
                  className="w-full bg-gray-100 text-gray-700 rounded-full py-4 pl-12 pr-6 focus:outline-none focus:ring-2 focus:ring-[#57b846] transition-all"
                  type="password"
                  name="password"
                  placeholder="Password"
                />
              </div>
              <div className="text-red-500 text-sm mt-1 ml-4">
                {formik.touched.password && formik.errors.password}
              </div>
            </div>

            {/* Submit Button */}
            {userLoading ? (
              <DisabledButton />
            ) : (
              <button
                type="submit"
                className="w-full bg-[#57b846] hover:bg-gray-800 text-white font-bold py-4 rounded-full uppercase tracking-widest transition-colors duration-300 shadow-md"
              >
                Login
              </button>
            )}

            <div className="text-center mt-6 text-gray-600">
              Don't have an account?{" "}
              <Link to="/register" className="text-[#57b846] font-semibold hover:underline">
                Create account
              </Link>
            </div>
          </form>
        </div>
      </div>
    </section>
  );
};

export default Login;
